using System.Security.Cryptography;
using System.Text.Json;
using Ai00.Connector.Adapters.VisMockup;
using Ai00.Connector.AppHost;
using Xunit;
namespace Ai00.Connector.Tests;
public sealed class CaptureDeliveryQueueTests : IDisposable
{
    readonly string root = Path.Combine(Path.GetTempPath(), "ai00-delivery-" + Guid.NewGuid().ToString("N"));
    readonly CaptureDeliveryScope scope = new("tenant", "actor", "project", "bop", "sha256:" + new string('a', 64), "sha256:" + new string('b', 64), "device", "document-session", "run");
    string Db => Path.Combine(root, "delivery.sqlite");
    public CaptureDeliveryQueueTests() { Directory.CreateDirectory(root); }
    LocalCaptureArtifact Capture() { var path = Path.Combine(root, "actual.png"); var bytes = Convert.FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAusB9Wl6JZcAAAAASUVORK5CYII="); File.WriteAllBytes(path, bytes); return new(path, "image/png", Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant(), bytes.Length, 1, 1, 1); }
    static JsonElement Receipt(LocalCaptureArtifact capture, string? hash = null) => JsonSerializer.SerializeToElement(new { artifact_id = "artifact-actual-response", media_type = "image/png", sha256 = hash ?? capture.Sha256, byte_size = capture.ByteSize });
    JsonElement CraftReceipt(LocalCaptureArtifact c, string operation = "op") => JsonSerializer.SerializeToElement(new { screenshot_gid = "screenshot-receipt", bop_version_gid = scope.BopVersionGid, operation_id = operation, capture_run_id = scope.CaptureRunId, artifact_ref = Receipt(c) });
    [Fact] public void CraftArtifactPropertyOrderDoesNotChangeReceiptIdentity() { var c = Capture(); var q = new CaptureDeliveryQueue(Db, root); var row = q.Enqueue(scope, "op", "a", "s", c); var uploaded = q.RecordUploaded(scope, row.DeliveryId, row.Revision, Receipt(c)); var ack = JsonSerializer.SerializeToElement(new { screenshot_gid = "screenshot-receipt", bop_version_gid = scope.BopVersionGid, operation_id = "op", capture_run_id = scope.CaptureRunId, artifact_ref = new { byte_size = c.ByteSize, sha256 = c.Sha256, media_type = c.MediaType, artifact_id = "artifact-actual-response" } }); Assert.Equal("attached", q.RecordAttached(scope, row.DeliveryId, uploaded.Revision, ack).State); }
    [Fact] public void AttachmentRequiresMatchingCraftReceipt() { var c = Capture(); var q = new CaptureDeliveryQueue(Db, root); var row = q.Enqueue(scope, "op", "a", "s", c); var uploaded = q.RecordUploaded(scope, row.DeliveryId, row.Revision, Receipt(c)); Assert.Throws<InvalidDataException>(() => q.RecordAttached(scope, row.DeliveryId, uploaded.Revision, CraftReceipt(c, "other-op"))); Assert.Equal("uploaded", Assert.Single(q.Pending(scope)).State); var attached = q.RecordAttached(scope, row.DeliveryId, uploaded.Revision, CraftReceipt(c)); Assert.Equal("screenshot-receipt", attached.AttachmentReceipt!.Value.GetProperty("screenshot_gid").GetString()); }
    [Fact] public void CaptureAndReceiptSurviveRestartWithoutRecapturing() { var capture = Capture(); var q = new CaptureDeliveryQueue(Db, root); var row = q.Enqueue(scope, "op", "attempt", "slot", capture); Assert.Equal("captured", row.State); var reopened = new CaptureDeliveryQueue(Db, root); Assert.Single(reopened.Pending(scope)); var uploaded = reopened.RecordUploaded(scope, row.DeliveryId, row.Revision, Receipt(capture)); Assert.Equal("uploaded", uploaded.State); var again = new CaptureDeliveryQueue(Db, root); Assert.Equal("uploaded", Assert.Single(again.Pending(scope)).State); Assert.Equal(capture.Sha256, Assert.Single(again.Pending(scope)).Capture.Sha256); }
    [Fact] public void EnqueueIsIdempotentButCannotReplaceExistingImage() { var c = Capture(); var q = new CaptureDeliveryQueue(Db, root); var first = q.Enqueue(scope, "op", "a", "s", c); Assert.Equal(first.DeliveryId, q.Enqueue(scope, "op", "a", "s", c).DeliveryId); File.AppendAllText(c.Path, "different"); var bytes = File.ReadAllBytes(c.Path); Assert.Throws<InvalidDataException>(() => q.Enqueue(scope, "op", "a", "s", c with { Sha256 = Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant(), ByteSize = bytes.Length })); }
    [Fact] public void QueueRejectsChangedBytesAndNeverInventsUploadedArtifact() { var c = Capture(); var q = new CaptureDeliveryQueue(Db, root); Assert.Throws<InvalidDataException>(() => q.Enqueue(scope, "op", "a", "s", c with { Sha256 = new string('0', 64) })); var row = q.Enqueue(scope, "op", "a", "s", c); Assert.Throws<InvalidDataException>(() => q.RecordUploaded(scope, row.DeliveryId, row.Revision, Receipt(c, new string('0', 64)))); Assert.Equal("captured", Assert.Single(q.Pending(scope)).State); }
    [Fact] public void ScopeAndRevisionFenceLateResults() { var c = Capture(); var q = new CaptureDeliveryQueue(Db, root); var row = q.Enqueue(scope, "op", "a", "s", c); Assert.Empty(q.Pending(scope with { ActorId = "other" })); Assert.Throws<InvalidOperationException>(() => q.RecordUploaded(scope with { ActorId = "other" }, row.DeliveryId, row.Revision, Receipt(c))); var uploaded = q.RecordUploaded(scope, row.DeliveryId, row.Revision, Receipt(c)); Assert.Throws<InvalidOperationException>(() => q.RecordAttached(scope, row.DeliveryId, row.Revision, CraftReceipt(c))); q.RecordAttached(scope, row.DeliveryId, uploaded.Revision, CraftReceipt(c)); Assert.Empty(q.Pending(scope)); }
    [Fact] public void CancelStopsLateAttachmentAcrossRestartButRetainsEvidence() { var c = Capture(); var q = new CaptureDeliveryQueue(Db, root); var row = q.Enqueue(scope, "op", "a", "s", c); q.Cancel(scope); var reopened = new CaptureDeliveryQueue(Db, root); Assert.Empty(reopened.Pending(scope)); var uploaded = reopened.RecordUploaded(scope, row.DeliveryId, row.Revision, Receipt(c)); Assert.Throws<InvalidOperationException>(() => reopened.RecordAttached(scope, row.DeliveryId, uploaded.Revision, CraftReceipt(c))); Assert.True(File.Exists(c.Path)); Assert.Throws<InvalidOperationException>(() => reopened.Enqueue(scope, "op2", "a", "s2", c)); }
    [Fact] public void QueueAppliesBackpressureBeforeCaptureEvidenceIsLost() { var c = Capture(); var q = new CaptureDeliveryQueue(Db, root, maxPendingBytes: c.ByteSize); q.Enqueue(scope, "one", "a", "s1", c); Assert.Throws<InvalidOperationException>(() => q.Enqueue(scope, "two", "a", "s2", c)); Assert.Single(q.Pending(scope)); }
    public void Dispose() { Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools(); Directory.Delete(root, true); }
}
